import React, { useEffect, useState } from "react";
import "../styles/homePage.css"
import { Slide } from 'react-slideshow-image';
import 'react-slideshow-image/dist/styles.css';
import legoman from "../resources/legoman.jpg"
import legowoman from "../resources/legowoman.jpg"
import legoBricks from "../resources/legoBricks.png"
import adults from "../resources/adults.png"
import kids from "../resources/kids.png"
import teens from "../resources/teens.png"
import { useNavigate } from "react-router";
import ProductTag from "../components/ProductTag";
import useApiGet from "../hooks/useApiGet";
import calculateDiscountPercentage from "../utilities/calculateDiscountPercentage";

export default function HomePage() {

    const navigate = useNavigate()
    const [newProducts, ,] = useApiGet(`products?page=1&count=12&orderBy=createdAt&ascending=false`)
    const [recommendedProducts, ,] = useApiGet("products/recommended?limit=12")
    useEffect(() => {
        function isElementInViewport(el) {
            var rect = el.getBoundingClientRect();

            return (
                rect.top >= 0 &&
                rect.bottom <= (window.innerHeight * 1.2 || document.documentElement.clientHeight)
            );
        }

        setTimeout(() => {
            document.getElementById('anim-shop-all-navigation-div').classList.add('anim')
        }, 10)

        let elementsToAnim = [
            document.getElementById('anim-age-group-1'),
            document.getElementById('anim-age-group-2'),
            document.getElementById('anim-age-group-3'),
            document.getElementById('anim-legoman'),
            document.getElementById('anim-legowoman'),
            document.getElementById('anim-check-our-products'),
        ]

        const handleScroll = () => {

            const elementsToPersist = []
            for (let element of elementsToAnim) {
                console.log(isElementInViewport(element))
                if (isElementInViewport(element)) {
                    element.classList.add('anim')
                }
                else elementsToPersist.push(element)
            }

            elementsToAnim = [...elementsToPersist]
            if (elementsToAnim.length == 0)
                window.removeEventListener("scroll", handleScroll);
        };

        window.addEventListener("scroll", handleScroll);
        return () => {
            window.removeEventListener("scroll", handleScroll);
        };
    }, []);

    return (
        <div className="center-container">
            <div className="home-page-container">
                <p className="home-page-category-title above-products-title">New products</p>
                <ProductInfoInSlider products={newProducts} />
                <div className="shop-all-navigation-border">
                    <div id="anim-shop-all-navigation-div" className="shop-all-navigation-div">
                        <img className="lego-bricks-image" src={legoBricks} />
                        <p className="shop-all-navigation-title  lego-font">Welcome to LegoLikeBricks</p>
                        <p className="light-font shop-all-navigation-description">From intricate designs to limitless constructions, each product invites you to reimagine the way you build and play. Happy building!</p>
                        <button onClick={() => navigate("./shop-all")} className="shop-all-navigation-button">Check products</button>
                    </div>
                </div>

                <div className="home-page-bestsellers">
                    <p className="home-page-category-title bestsellers above-products-title">Bestsellers</p>
                    <Recommendations recommendedProducts={recommendedProducts} />
                </div>

                <div id="age-groups" className="age-groups">
                    <p className="home-page-category-title lego-font">Age groups</p>
                    <div id="anim-age-group-1" className="age-group left">
                        <img className="age-group-img" src={kids} />
                        <div className="age-group-description">
                            <p className="age-group-title bold-font">KIDS</p>
                            <p className="age-group-content left light-font">Explore a world of creativity at LegoLikeBricks, where our vibrant and compatible building blocks go beyond play. Unleash imagination, nurture fine motor skills, and cultivate a lifelong love for creativity.</p>
                            <button className="explore-more-button shop-all-navigation-button desktop-only">Explore more</button>
                        </div>
                        <i className="fas mobile-only left fa-chevron-right age-group-button" />
                    </div>

                    <div id="anim-age-group-2" className="age-group right">
                        <i className="fas mobile-only fa-chevron-left age-group-button right" />

                        <div className="age-group-description right">
                            <p className="age-group-title right bold-font">TEENS</p>
                            <p className="age-group-content right light-font"> Designed for teenagers and adults, completing these intricate builds not only provides a satisfying challenge but also instills a profound sense of confidence and pride.</p>
                            <button className="explore-more-button shop-all-navigation-button desktop-only right">Explore more</button>
                        </div>
                        <img className="age-group-img" src={teens} />
                    </div>

                    <div id="anim-age-group-3" className="age-group left">
                        <img className="age-group-img" src={adults} />
                        <div className="age-group-description">
                            <p className="age-group-title bold-font">ADULTS</p>
                            <p className="age-group-content left light-font">Whether you're a seasoned collector or seeking a new level of building excitement, our sets are the perfect gift to inspire creativity and fuel the passion for construction.</p>
                            <button className="explore-more-button shop-all-navigation-button desktop-only">Explore more</button>
                        </div>
                        <i className="fas mobile-only left fa-chevron-right age-group-button" />
                    </div>
                </div>

                <div className="about-us">
                    <p className="home-page-category-title">Not lego, but close enough</p>

                    <div className="about-us-content">

                        <img id="anim-legoman" className="legoman" src={legoman} />
                        <p className="medium-font">Welcome to LegoLikeBricks: Your Gateway to Creative Building!</p>
                        <p className="light-font">LegoLikeBricks is your ultimate destination for a world of creative building possibilities! At LegoLikeBricks, we bring you a unique and exciting experience with our high-quality building blocks that emulate the beloved charm of Lego.</p><br />

                        <p className="medium-font">A Hub for Imagination</p>
                        <p className="light-font"> Dive into a realm where imagination knows no bounds, and each block is a gateway to endless adventures. LegoLikeBricks is more than just an e-commerce platform; it's a hub for enthusiasts, dreamers, and builders of all ages who seek the thrill of constructing their visions.</p><br />

                        <img id="anim-legowoman" className="legowoman" src={legowoman} />
                        <p className="medium-font">Affordable Alternatives, Accessible Joy</p>
                        <p className="light-font">What sets us apart is our commitment to providing an affordable and accessible alternative to official Lego bricks, ensuring that the joy of building is within reach for everyone. Our detailed and captivating sets are designed to inspire both teenagers and adults, offering a perfect blend of challenge, accomplishment, and the sheer delight of creating something extraordinary.</p><br />

                        <p className="medium-font">Beyond a Store: Building a Community of Creativity</p>
                        <p className="light-font">LegoLikeBricks isn't just a store; it's a community that celebrates the art of building and the boundless power of imagination. Join us on this exciting journey, and let your creativity take center stage. Discover, build, and embrace the endless possibilities that LegoLikeBricks has to offer - where the magic of construction comes to life!</p><br />
                        <button onClick={() => navigate("./shop-all")} id="anim-check-our-products" className="shop-all-navigation-button check-our-products">Check our products</button>
                    </div>
                </div>

            </div>
        </div >
    )
}

const Recommendations = ({ recommendedProducts }) => {
    console.log(recommendedProducts)
    return (
        <div className="recommendation-div">
            {
                recommendedProducts?.map(product => (
                    <RecommendationItem product={product} />
                ))
            }
        </div>
    )
}

const RecommendationItem = ({ product }) => {
    const navigate = useNavigate()
    console.log(product)
    return (
        <div onClick={() => navigate(`../product/${product.productId}`)} className="recommendation-slide shop-item-div">
            <img className="recommendation-image" src={product.multimediaInfo.imageUrls[0]} />
            <div className="product-info">
                <p><i className="fas fa-star" /> {product.rating}</p>
                <p>{`(${product.ratingCount} reviews)`}</p>
            </div>
            <p className="product-info-title medium-font">{product.name}</p>
            <div className='product-info-price-div'>
                <p className="product-info-price">${product.discountedPrice !== -1 ? product.discountedPrice : product.price}</p>
                {
                    product.discountedPrice !== -1 &&
                    <div className="product-info-previous-price">
                        <p className="">Before:
                            <span className="crossed-price"> ${product.price}</span>
                        </p>
                        <p className="recommendation-item-name-discount-percent medium-font">-{calculateDiscountPercentage(product?.price, product?.discountedPrice)}%</p>
                    </div>
                }
            </div>
            <button onClick={() => navigate(`../product/${product.productId}`)} className="product-info-check-details">Buy now</button>
        </div>
    )
}


const ProductInfoInSlider = ({ products }) => {
    const properties = {
        prevArrow: <button className="next-slide-button"><i className="fas fa-chevron-left age-group-button black" /></button>,
        nextArrow: <button className="next-slide-button"><i className="fas fa-chevron-right age-group-button black black" /></button>
    }

    const slidesToShow = window.innerWidth < 710 ? 2 : window.innerWidth < 900 ? 3 : 4

    return (
        <Slide key={products?.length ?? 0} slidesToScroll={1} slidesToShow={slidesToShow}  {...properties}>
            {
                products?.map(product => (
                    <HomePageSlideItem key={product.id} product={product} />
                ))
            }
        </Slide>
    )
}

function HomePageSlideItem({ product }) {
    const navigate = useNavigate()
    return (
        <div onClick={() => navigate(`../product/${product.productId}`)} className="home-page-slide-wrapper">
            <div className="home-page-slide shop-item-div">
                <img className="product-info-image" src={product.multimediaInfo.imageUrls[0]} />
                <ProductTag />
                <div className="product-info">
                    <p><i className="fas fa-star" /> {product.rating}</p>
                    <p>{`(${product.ratingCount} reviews)`}</p>
                </div>
                <p className="product-info-title medium-font">{product.name}</p>
                <div className='product-info-price-div'>
                    <p className="product-info-price">${product.discountedPrice !== -1 ? product.discountedPrice : product.price}</p>
                    {
                        product.discountedPrice !== -1 &&
                        <div className="product-info-previous-price">
                            <p className="">Before:
                                <span className="crossed-price"> ${product.price}</span>
                            </p>
                            <p className="recommendation-item-name-discount-percent medium-font">-{calculateDiscountPercentage(product?.price, product?.discountedPrice)}%</p>
                        </div>
                    }
                </div>
                <button onClick={() => navigate(`../product/${product.productId}`)} className="product-info-check-details">Buy now</button>
            </div>
        </div>
    )
}
