import React, { useEffect, useState } from "react";
import "../styles/shopAllPage.css"
import useSticky from "../hooks/useSticky";
import useApiGet from "../hooks/useApiGet";
import Loader from "../components/Loader";
import "../styles/checkbox.css"
import calculateDiscountPercentage from "../utilities/calculateDiscountPercentage";
import { useNavigate } from "react-router-dom";

export default function ShopAllPage() {
    const [isFiltersOpened, setIsFiltersOpened] = useState(false)
    const [isBigLayout, setisBigLayout] = useState(false)
    const [orderBy, setOrderBy] = useState('name')
    const [isAscending, setIsAscending] = useState(true)
    const [page, setPage] = useState(1)
    const [products, setProducts] = useState([])
    const [loadedProducts, , isLoading] = useApiGet(`products?page=${page}&count=12&orderBy=${orderBy}&ascending=${isAscending}`)

    useEffect(() => {
        if (loadedProducts !== null)
            setProducts(products => [...products, ...loadedProducts]);
    }, [loadedProducts]);

    const handleLoadMore = () => {
        setPage(page + 1)
    }

    const handleSelectValue = (value) => {
        if (value == 0) {
            setOrderBy('name')
        }
        else if (value == 1) {
            setOrderBy('createdAt')
            setIsAscending(false)
        }
        else if (value == 2) {
            setOrderBy('price')
            setIsAscending(true)
        }
        else if (value == 3) {
            setOrderBy('price')
            setIsAscending(false)
        }
        setPage(1)
        setProducts([])
    }

    if (isLoading && products == null)
        return (
            <div className="loader-div">
                <Loader />
            </div>)

    if (isFiltersOpened)
        return <Filters onCloseFilters={() => { setIsFiltersOpened(false) }} />

    return (
        <div className="shop-all-page-container">
            <div className='side-filters desktop-only'>
                <FiltersOptions />
            </div>
            <div className="shop-all-page-div">
                <FilterHeader
                    onChangeLayout={(val) => setisBigLayout(val)}
                    onOpenFilters={() => setIsFiltersOpened(true)} />
                <ListOfProducts products={products} isBigLayout={isBigLayout} />
                {
                    loadedProducts && loadedProducts.length > 0 &&
                    <div className="load-more-reviews load-more-reviews-all">
                        {
                            isLoading ?
                                <Loader />
                                : <p className="load-more-text bold-font clickable" onClick={handleLoadMore}>Load more</p>
                        }
                    </div>
                }
            </div>

        </div>
    )
}

const ListOfProducts = ({ isBigLayout, products }) => {
    return (
        <div className={`${isBigLayout ? 'big-list-of-products' : 'list-of-products'}`}>
            {
                products?.map(product => (
                    <ListItem key={product.id} isBigLayout={isBigLayout} product={product} />
                ))
            }
        </div>
    )
}

const ListItem = ({ product, isBigLayout }) => {
    const [selectedImage, setSelectedImage] = useState(product.multimediaInfo.imageUrls[0])
    const navigate = useNavigate()
    return (
        <div onClick={() => navigate(`../product/${product.productId}`)} className={`recommendation-slide ${isBigLayout ? 'shop-item-div-big' : 'shop-item-div'}`}>
            <img className={`${isBigLayout ? 'recommendation-image-big' : ''} recommendation-image`} src={selectedImage} />
            <div className={`shop-item-info-div ${isBigLayout ? 'shop-item-info-div-big' : ''}`}>
                <div className="shop-item-info-div-content">
                    <div className="product-info">
                        <p><i className="fas fa-star" /> {product.rating}</p>
                        <p>{`(${product.ratingCount} reviews)`}</p>
                    </div>
                    <p className="product-info-title medium-font">{product.name}</p>
                    <div className={`${isBigLayout ? 'product-info-price-div-big' : ''} product-info-price-div`}>
                        <p className="product-info-price">${product.discountedPrice !== -1 ? product.discountedPrice : product.price}</p>
                        {
                            product.discountedPrice !== -1 &&
                            <div className="product-info-previous-price">
                                <p className="">Before:
                                    <span className="crossed-price"> ${product.price}</span>
                                </p>
                                <p className="recommendation-item-name-discount-percent medium-font">-{calculateDiscountPercentage(product?.price, product?.discountedPrice)}%</p>
                            </div>
                        }
                    </div>
                    {isBigLayout &&
                        <button onClick={() => navigate(`../product/${product.productId}`)} className={`product-info-check-details`}>Buy now</button>
                    }
                </div>
                {isBigLayout &&
                    <SmallGallery onSelectedImage={(img) => setSelectedImage(img)} product={product} />
                }
            </div>
            {!isBigLayout &&
                <button onClick={() => navigate(`../product/${product.productId}`)} className={`product-info-check-details`}>Buy now</button>
            }
        </div>
    )
}

function SmallGallery({ onSelectedImage, product }) {
    const handleSelectedImage = (e, img) => {
        e.stopPropagation();
        onSelectedImage(img)
    }
    return (
        <div className="big-layout-gallery">
            {
                product.multimediaInfo.imageUrls.map((img, idx) => (
                    <div key={idx}
                        className="each-slide-effect">
                        <img onClick={(e) => handleSelectedImage(e, img)} loading="lazy" alt="" className={`each-big-layout-small-image`} src={img} />
                    </div>
                ))
            }
        </div>
    )
}

const FilterHeader = ({ onChangeLayout, onOpenFilters }) => {
    const isSticky = useSticky();
    const [isCompactLayout, setIsCompactLayout] = useState(false)

    const handleChangeLayout = (action) => {
        setIsCompactLayout(action)
        onChangeLayout(action)
    }

    return (
        <>
            <div className={`mobile-only sticky-filters ${isSticky ? 'make-filters-sticky' : ''}`}>
                <div className="select-layouts-div">
                    <i onClick={() => handleChangeLayout(false)} className={`fas ${isCompactLayout ? 'non-active-layout-icon' : ''}  fa-th-large`}></i>
                    <p>|</p>
                    <i onClick={() => handleChangeLayout(true)} className={`fas ${isCompactLayout ? '' : 'non-active-layout-icon'} fa-th`}></i>
                </div>
                <div className="select-filters-div">
                    <p onClick={onOpenFilters}>Filters</p>
                    <p>|</p>
                    <p>Sort by</p>
                </div>
            </div>
            <div className="desktop-only desktop-filter">
                <div className="sort-by-div">
                    <p className="medium-font">Sort by:</p>
                    <select>
                        <option value={0}>Recommended</option>
                        <option value={1}>Newly released</option>
                        <option value={2}>Price, low to high</option>
                        <option value={3}>Price, high to low</option>
                    </select>
                </div>
            </div>
        </>
    )
}

const Filters = ({ onCloseFilters }) => {
    return (
        <div className="filters-shadow">
            <div className="filters-container">
                <div onClick={onCloseFilters} className="filters-header">
                    <p>Close</p>
                    <i className="fas fa-times" />
                </div>
                <FiltersOptions />
                <div className="filters-button-div">
                    <button className="filters-button">Show products</button>
                </div>
            </div>
        </div>
    )
}

const FiltersOptions = () => {
    return (
        <div className="filters-content">
            <ExpandableDiv
                title='Price Range'
                content={
                    <div className="checkboxes-div">
                        <FilterOption property={'$1 - $50'} />
                        <FilterOption property={'$50 - $100'} />
                        <FilterOption property={'$100 - $200'} />
                        <FilterOption property={'$200+'} />
                    </div>
                }
            />
            <ExpandableDiv
                title='Age groups'
                content={
                    <div className="checkboxes-div">
                        <FilterOption property={'Kids'} />
                        <FilterOption property={'Teens'} />
                        <FilterOption property={'Adults'} />
                    </div>
                }
            />
            <ExpandableDiv
                title='Categories'
                content={
                    <div className="checkboxes-div">
                        <FilterOption property={'Harry-Potter'} />
                        <FilterOption property={'Star-Wars'} />
                        <FilterOption property={'Marvel asdas asd '} />
                        <FilterOption property={'Marvel'} />
                        <FilterOption property={'Marvel'} />
                        <FilterOption property={'Marvel'} />
                        <FilterOption property={'Marvel'} />
                        <FilterOption property={'Marvel'} />
                        <FilterOption property={'Marvel'} />
                        <FilterOption property={'Marvel'} />
                        <FilterOption property={'Marvel'} />
                    </div>
                }
            />
        </div>
    )
}

const FilterOption = ({ property }) => {
    return (
        <div className="checkboxes-row">

            <label class="container">
                <p className="checkboxes-row-property">{property}</p>
                <input type="checkbox" />
                <span class="checkmark" />
            </label>
        </div>
    )
}

const ExpandableDiv = ({ title, content }) => {

    const [isExpanded, setIsExpanded] = useState(true)

    return (
        <div className="expandable-div">
            <div
                onClick={() => setIsExpanded(!isExpanded)}
                className={`expandable-div-header`}>
                <p className="expandable-div-title bold-font">{title}</p>
                <i className={`fas expandable-icon fa-chevron-up ${isExpanded ? "expanded" : ''}`}></i>
            </div>
            {
                isExpanded &&
                <div className="expandable-div-content" >
                    {content}
                </div>
            }
        </div >
    )
}