import React from "react";

export default function Confirm({ price, quantity }) {
    return (
        <div className="stripe-div">
            <Order
                price={price}
                quantity={quantity} />
        </div>
    )
}

function Order({ price, quantity }) {
    return (
        <>
            <p className="expandable-purchase-order">Order</p>
            <div className="expandable-purchase-total">
                <div>
                    <p>Subtotal</p>
                    <p>{quantity} x ${price}</p>
                </div>
                <div>
                    <p>Shipping</p>
                    <p>FREE</p>
                </div>
                <hr />
                <div>
                    <p className="bold-font">Total</p>
                    <p className="bold-font">${quantity * price}</p>
                </div>
            </div>
        </>
    )
}